def find_all_good_products(max_prod):
    good_products = set()
    # We can't just iterate over all sets.
    # But we know that for n=3, the products are k^2.
    # For n=4, what could they be?
    # Let's try to build sets by picking elements.
    # If the product is at most 2000, the elements must be small.
    # The maximum element can't be more than 2000/ (2*3*4) = 83.
    elements = list(range(2, 200))

    # For n=3:
    for i, j, k in combinations(elements, 3):
        if i*j*k <= max_prod:
            if is_good_set_fast([i, j, k]):
                good_products.add(i*j*k)
        else:
            # Since combinations are sorted, we can break
            pass

    # For n=4:
    for i, j, k, l in combinations(elements, 4):
        if i*j*k*l <= max_prod:
            if is_good_set_fast([i, j, k, l]):
                good_products.add(i*j*k*l)
        else:
            pass

    # For n=5:
    for i, j, k, l, m in combinations(elements, 5):
        if i*j*k*l*m <= max_prod:
            if is_good_set_fast([i, j, k, l, m]):
                good_products.add(i*j*k*l*m)
        else:
            pass

    return good_products

print(sorted(list(find_all_good_products(2000))))

