def find_n4_good_products(max_prod):
    good_products = set()
    for a in range(2, max_prod // 60):
        for b in range(a + 1, max_prod // (a * 6)):
            for c in range(b + 1, max_prod // (a * b)):
                if gcd(a, gcd(b, c)) != 1:
                    continue
                # Check if {a,b,c} is "almost" good (a,b,c satisfies any 2 from {a,b,c})
                # Wait, the condition is: for any two of {a,b,c,d}, there's another in {a,b,c,d}
                # Let's just try all d.
                for d in range(c + 1, max_prod // (a * b * c) + 1):
                    if a*b*c*d <= max_prod:
                        if is_good_set_fast([a, b, c, d]):
                            good_products.add(a*b*c*d)
    return good_products

print(sorted(list(find_n4_good_products(2000))))

